INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist proprietäre Software immer kostenpflichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch kostenlos verteilt werden"}, {"text": "Ja", "correct": false, "because": "Preis nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptmerkmal proprietärer Software?', 3, '[{"text": "Geschlossener Quellcode", "correct": true, "because": "Zugriff auf Code eingeschränkt"}, {"text": "Freie Modifikation", "correct": false, "because": "Typisch für Open Source"}, {"text": "Manuelle Installation", "correct": false, "because": "Nicht spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat proprietäre Software?', 5, '[{"text": "Lizenzbeschränkungen", "correct": true, "because": "Regelt Nutzung"}, {"text": "Eingeschränkte Modifikation", "correct": true, "because": "Quellcode nicht verfügbar"}, {"text": "Freie Verteilung", "correct": false, "because": "Eingeschränkt durch Lizenz"}, {"text": "Kein Support", "correct": false, "because": "Oft mit Support"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Proprietäre Software hat oft Nutzungsbedingungen. b) Sie ist immer Open Source.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Gegenteil"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung proprietärer Software?', 4, '[{"text": "Lizenzbedingungen", "correct": false, "because": "Müssen eingehalten werden"}, {"text": "Supportverträge", "correct": false, "because": "Können wichtig sein"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob proprietäre Software modifiziert werden darf?', 2, '[{"text": "Nein", "correct": true, "because": "Quellcode meist nicht verfügbar"}, {"text": "Ja", "correct": false, "because": "Eingeschränkt durch Lizenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Lizenz bei proprietärer Software?', 3, '[{"text": "Regelt Nutzung", "correct": true, "because": "Definiert Rechte und Pflichten"}, {"text": "Ermöglicht Modifikation", "correct": false, "because": "Verhindert Änderungen"}, {"text": "Manuelle Verteilung", "correct": false, "because": "Nicht lizenzbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele gibt es für proprietäre Software?', 5, '[{"text": "Microsoft Windows", "correct": true, "because": "Geschlossener Quellcode"}, {"text": "Adobe Photoshop", "correct": true, "because": "Lizenzbeschränkt"}, {"text": "Linux Kernel", "correct": false, "because": "Open Source"}, {"text": "GIMP", "correct": false, "because": "Open Source"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Proprietäre Software bietet oft Support. b) Sie ist immer unsicher. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von Implementierung ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für proprietäre Software?', 4, '[{"text": "Lizenzvereinbarung", "correct": false, "because": "Regelt Nutzung"}, {"text": "Systemvoraussetzungen", "correct": false, "because": "Sichern Funktion"}, {"text": "Musikwiedergabe", "correct": true, "because": "Irrelevant für Software"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist proprietäre Software dasselbe wie Open Source?', 2, '[{"text": "Nein", "correct": true, "because": "Open Source ist frei zugänglich"}, {"text": "Ja", "correct": false, "because": "Gegensätzliche Modelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einschränkungen hat proprietäre Software?', 4, '[{"text": "Eingeschränkte Modifikation", "correct": true, "because": "Quellcode geschützt"}, {"text": "Nutzungsbedingungen", "correct": true, "because": "Lizenz schränkt ein"}, {"text": "Freie Verteilung", "correct": false, "because": "Eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass proprietäre Software keine Updates bietet. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Updates oft verfügbar"}, {"text": "Ja", "correct": false, "because": "Updates üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung proprietärer Software?', 3, '[{"text": "Lizenzeinhaltung", "correct": true, "because": "Vermeidet rechtliche Probleme"}, {"text": "Freie Modifikation", "correct": false, "because": "Nicht möglich"}, {"text": "Manuelle Installation", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Proprietäre Software hat oft Support. b) Sie ist immer Open Source.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Gegenteil"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet proprietäre Software?', 5, '[{"text": "Professioneller Support", "correct": true, "because": "Oft vom Hersteller"}, {"text": "Optimierte Benutzeroberfläche", "correct": true, "because": "Fokus auf Nutzer"}, {"text": "Freie Modifikation", "correct": false, "because": "Nicht möglich"}, {"text": "Unbegrenzte Verteilung", "correct": false, "because": "Lizenzbeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei proprietärer Software unwichtig?', 3, '[{"text": "Lizenzbedingungen", "correct": false, "because": "Müssen eingehalten werden"}, {"text": "Systemkompatibilität", "correct": false, "because": "Sichert Funktion"}, {"text": "Bildschirmauflösung", "correct": true, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob proprietäre Software für Unternehmen üblich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Häufig wegen Support"}, {"text": "Nein", "correct": false, "because": "Weit verbreitet"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann proprietäre Software frei verteilt werden?', 3, '[{"text": "Nein", "correct": true, "because": "Lizenz schränkt Verteilung ein"}, {"text": "Ja", "correct": false, "because": "Eingeschränkt durch Lizenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu proprietärer Software?', 4, '[{"text": "Nutzung von Microsoft Office", "correct": true, "because": "Lizenzpflichtige Software"}, {"text": "Entwicklung mit Linux", "correct": false, "because": "Open Source"}, {"text": "Musikwiedergabe", "correct": false, "because": "Kein Softwarekontext"}]');
